package io.github.diodeme.ji.provider.http;

import io.github.diodeme.ji.ai.ProviderFailure;
import java.time.Duration;
import java.util.Map;
import java.util.Optional;

public final class ProviderErrors {
    private ProviderErrors() {}

    public static ProviderFailure fromStatus(String provider, int status, Optional<String> providerCode,
                                             Optional<Duration> retryAfter) {
        String code;
        if (status == 401) code = "provider.authentication_failed";
        else if (status == 403) code = "provider.permission_denied";
        else if (status == 408 || status == 504) code = "provider.timeout";
        else if (status == 429) code = "provider.rate_limited";
        else if (status >= 500) code = "provider.unavailable";
        else code = "provider.request_rejected";
        var parameters = new java.util.LinkedHashMap<String, String>();
        parameters.put("provider", provider);
        parameters.put("status", Integer.toString(status));
        providerCode.filter(value -> !value.isBlank()).ifPresent(value -> parameters.put("providerCode", value));
        return new ProviderFailure(code, Map.copyOf(parameters), retryAfter);
    }

    public static ProviderFailure timeout(String provider, String phase) {
        return new ProviderFailure("provider.timeout", Map.of("provider", provider, "phase", phase), Optional.empty());
    }

    public static ProviderFailure redirect(String provider, String reason) {
        return new ProviderFailure("provider.redirect_rejected", Map.of("provider", provider, "reason", reason), Optional.empty());
    }

    public static ProviderFailure invalid(String provider, String reason) {
        return new ProviderFailure("provider.invalid_response", Map.of("provider", provider, "reason", reason), Optional.empty());
    }
}
